// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DepositLog} from "../src/DepositLog.sol";

contract InvMutTest is Test {
    DepositLog c;
    function setUp() public { c = new DepositLog(); }
    function testFuzz_property(address _logger, bool _status, address _nonOwner) public {
        vm.assume(_nonOwner != address(0));
        vm.assume(_nonOwner != address(this));
        vm.assume(_logger != address(0));
        vm.assume(_logger != _nonOwner);

        vm.prank(_nonOwner);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("setApprovedLogger(address,bool)", _logger, _status));
        assertTrue(!ok, "non-owner should not be able to call setApprovedLogger");
    }
}
